# Shared JS snippets for modal audit (copied into browser_automation scripts)
DET = """() => { const dlg = [...document.querySelectorAll('[role="dialog"]')].pop(); if (!dlg) return {open:false}; const H = innerHeight; const isScroller = el => { const cs = getComputedStyle(el); return /(auto|scroll)/.test(cs.overflowY) && el.scrollHeight > el.clientHeight + 1; }; const unreachable = []; dlg.querySelectorAll('button, [role="button"], input, textarea').forEach(el => { const r = el.getBoundingClientRect(); if (r.height === 0 || r.width === 0) return; if (r.bottom > H + 1 || r.top < -1) { let p = el.parentElement, ok = false; while (p && p !== dlg) { if (isScroller(p)) { ok = true; break; } p = p.parentElement; } if (!ok) unreachable.push((el.innerText || el.placeholder || el.getAttribute('data-testid') || el.tagName).slice(0, 40)); } }); const scrollers = [...dlg.querySelectorAll('*')].filter(isScroller).map(el => ({h: el.clientHeight, sh: el.scrollHeight, testid: el.getAttribute('data-testid')})); return {open: true, winH: H, unreachable, scrollers}; }"""
# Extended detector: also includes RN-web Touchables (div[tabindex="0"]) which have no role=button
DET2 = DET.replace("'button, [role=\"button\"], input, textarea'", "'button, [role=\"button\"], input, textarea, [tabindex=\"0\"]'")
